window.MG_LAZY_DATA["data/lazy/resources/security-v26-051-0bc21c60c246e721.json"]={sha256:"0bc21c60c246e721ca987c75549bc3cbe912d5ad48a8ede5fc735d95de265570",value:{"sources":[{"id":"v26-case-3382974f730f995a","url":"https://csrc.nist.gov/pubs/sp/800/218/final","title":"NIST SP 800-218: SSDF Version 1.1","titleEn":"NIST SP 800-218: SSDF Version 1.1","publisher":"NIST","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."}],"media":{"courses":[{"courseId":"security-v26-051","videos":[],"guides":[]}]},"related":{"courses":[{"courseId":"security-v26-051","related":[{"id":"security-v26-052","referenceUrls":["https://www.threatdragon.com/docs/","https://cheatsheetseries.owasp.org/cheatsheets/Threat_Modeling_Cheat_Sheet.html"],"title":"OWASP Threat Dragon：信任邊界與緩解驗證","titleEn":"OWASP Threat Dragon: trust boundaries and mitigation tests","why":"用兩課的可觀察驗收條件比較模型邊界：交付16列適用性表、證據索引、阻擋清單及一份可重跑的發布審查紀錄。","whyEn":"Compare model boundaries using observable acceptance criteria: Deliver a 16-row applicability matrix, evidence index, blocker list and reproducible release-review record.","difference":"對每條跨邊界資料流標出資料分類、身分、傳輸控制與失敗行為，為威脅寫可驗收的緩解測試。","differenceEn":"Label classification, identity, transport controls and failure behavior on every crossing, then define acceptance tests for threats.","transfer":"保留單位與邊界條件，僅轉移可證明相容的驗證方法。","transferEn":"Retain units and boundary conditions; transfer only demonstrably compatible verification methods.","practice":["覆蓋率以適用控制為分母；缺證據與不適用必須分欄，通過數不代表整體風險機率。 以下為自編合成案例，只在自己的離線文件、測試資料或明確授權的隔離環境演練；不是產品實測或生產設定。 20 個候選控制，4 個有核准理由而不適用；16 個適用中12個有新鮮證據。 有效覆蓋率=12/(20−4)=75%；若誤用全體分母會算成60%。","威脅模型是可修改的系統假設；緩解覆蓋=已有驗證的跨界流/所有跨界流，不能用威脅數推導攻擊機率。 以下為自編合成案例，只在自己的離線文件、測試資料或明確授權的隔離環境演練；不是產品實測或生產設定。 有8條跨界流；6條具有有效身分與加密測試，2條缺少備份存取測試。 已驗證跨界覆蓋=6/8=75%。","比較兩個模型的輸入、誤差與驗收條件，記錄不能沿用的假設。"],"practiceEn":["Coverage uses applicable controls as its denominator; missing evidence and non-applicability are separate states, not risk probabilities. This original synthetic case uses owned offline files, test data or an explicitly authorized isolated lab; it is not a product benchmark or a production configuration. There are 20 candidate controls, 4 approved non-applicable controls, and fresh evidence for 12 of the 16 applicable controls. Effective coverage=12/(20−4)=75%; using all controls instead produces 60%.","A threat model records revisable system assumptions; mitigation coverage is tested crossings divided by all crossings, not an attack probability. This original synthetic case uses owned offline files, test data or an explicitly authorized isolated lab; it is not a product benchmark or a production configuration. Eight flows cross trust boundaries; six have identity and transport tests, while two lack backup-access tests. Verified crossing coverage=6/8=75%.","Compare inputs, errors, and criteria; document assumptions that cannot be transferred."]},{"id":"security-v26-061","referenceUrls":["https://slsa.dev/spec/v1.2/build-provenance"],"title":"SLSA：來源證明與建置者信任配對","titleEn":"SLSA: provenance and trusted builder-signer pairs","why":"用兩課的可觀察驗收條件比較模型邊界：交付16列適用性表、證據索引、阻擋清單及一份可重跑的發布審查紀錄。","whyEn":"Compare model boundaries using observable acceptance criteria: Deliver a 16-row applicability matrix, evidence index, blocker list and reproducible release-review record.","difference":"為產物摘要、允許的簽署者與建置者配對、來源提交與輸入參數建立四道驗證。","differenceEn":"Define checks for artifact digest, allowed signer-builder pair, source commit and input parameters.","transfer":"保留單位與邊界條件，僅轉移可證明相容的驗證方法。","transferEn":"Retain units and boundary conditions; transfer only demonstrably compatible verification methods.","practice":["覆蓋率以適用控制為分母；缺證據與不適用必須分欄，通過數不代表整體風險機率。 以下為自編合成案例，只在自己的離線文件、測試資料或明確授權的隔離環境演練；不是產品實測或生產設定。 20 個候選控制，4 個有核准理由而不適用；16 個適用中12個有新鮮證據。 有效覆蓋率=12/(20−4)=75%；若誤用全體分母會算成60%。","四項條件必須同時成立；簽章有效只證明特定身分簽過，不能自動信任任意建置者。 以下為自編合成案例，只在自己的離線文件、測試資料或明確授權的隔離環境演練；不是產品實測或生產設定。 10份合成證明：8份摘要正確，其中7份有允許的配對，其中6份來源與參數也符合。 最後接受6/10=60%；不能把每關通過比例相加。","比較兩個模型的輸入、誤差與驗收條件，記錄不能沿用的假設。"],"practiceEn":["Coverage uses applicable controls as its denominator; missing evidence and non-applicability are separate states, not risk probabilities. This original synthetic case uses owned offline files, test data or an explicitly authorized isolated lab; it is not a product benchmark or a production configuration. There are 20 candidate controls, 4 approved non-applicable controls, and fresh evidence for 12 of the 16 applicable controls. Effective coverage=12/(20−4)=75%; using all controls instead produces 60%.","All four conditions must hold; a valid signature proves a signer signed, not that any builder is trusted. This original synthetic case uses owned offline files, test data or an explicitly authorized isolated lab; it is not a product benchmark or a production configuration. Ten synthetic attestations include eight correct digests, seven of those with allowed pairs, and six of those with matching source and parameters. Final acceptance is 6/10=60%; gate percentages cannot be added.","Compare inputs, errors, and criteria; document assumptions that cannot be transferred."]}],"references":[{"id":"v26-case-fc7498064b4397f3","url":"https://www.threatdragon.com/docs/","title":"OWASP Threat Dragon documentation","titleEn":"OWASP Threat Dragon documentation","publisher":"OWASP Threat Dragon","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."},{"id":"v26-case-ea079221bd09f9cb","url":"https://cheatsheetseries.owasp.org/cheatsheets/Threat_Modeling_Cheat_Sheet.html","title":"OWASP Threat Modeling Cheat Sheet","titleEn":"OWASP Threat Modeling Cheat Sheet","publisher":"OWASP","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."},{"id":"v26-case-cc97dd4df85a6cc2","url":"https://slsa.dev/spec/v1.2/build-provenance","title":"SLSA v1.2 build provenance","titleEn":"SLSA v1.2 build provenance","publisher":"SLSA","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."}],"overview":"比較相鄰案例與另一組案例的模型、可量測結果及可轉移的驗證方法。","overviewEn":"Compare neighboring and cross-group cases by model, measurable outcome, and transferable verification method."}]},"places":{"courses":[]},"vendors":{"courses":[],"vendors":[]}}};
